const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = data[0];
const h = data.slice(1);
const leftMax = new Array(n);
const rightMax = new Array(n);

leftMax[0] = h[0];
for (let i = 1; i < n; i++) {
  leftMax[i] = Math.max(leftMax[i - 1], h[i]);
}

rightMax[n - 1] = h[n - 1];
for (let i = n - 2; i >= 0; i--) {
  rightMax[i] = Math.max(rightMax[i + 1], h[i]);
}

let answer = 0;
for (let i = 0; i < n; i++) {
  if (Math.min(leftMax[i], rightMax[i]) > h[i]) answer++;
}

console.log(answer);
